import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易集说卷八","description":"周易集说 - 周易集说卷八","frontmatter":{"title":"周易集说卷八","description":"周易集说 - 周易集说卷八"},"headers":[],"relativePath":"zh/classics/jishuo/009.md","filePath":"zh/classics/jishuo/009.md"}'),r={name:"zh/classics/jishuo/009.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易集说卷八" tabindex="-1">周易集说卷八 <a class="header-anchor" href="#周易集说卷八" aria-label="Permalink to “周易集说卷八”">​</a></h1><p>钦定四库全书</p><p>宋俞琰撰</p><p>䷭ 巽下坤上</p><p>「升」，元亨。用见大人，勿恤，南征吉。</p><p>「升」，进而上也。萃、升皆以坤上坤下取义。萃三阴聚于下，倒转为「升」，则三阴升于上，下「巽」而上顺。九二以刚德居中，与六五相应，是以「元亨」。「大人」，指九二。「用见」与「利见」不同，「利见」者，宜见之。「用见」，将变动而有为，则见之也。既见则有庆，故勿劳忧恤。「南征」，前进也。「巽」居东南，「坤」居西南，皆南方之卦。南方阳明之地，进则遂其升而得行其志，故「吉」。释文云：「用见，本或作利见。」初六：允升，大吉。</p><p>「允升」者，初以四之允而升也。初与四虽不相应，然彼之柔以时升，此之柔亦以时升，彼此盖相信相从也。在下而升者，得上之人信从而不疑，是以「大吉」。</p><p>九二：孚乃利用礿，无咎。</p><p>二、五虽相应，有九三阻于其前而莫能升，故不言「升」。「萃」与「升」相反，而「孚乃利用礿」，俱言于下卦之中爻，何也？「礿」所以享上也。六二求萃于上，九二亦求升于上，故其义同而有小异者。「萃」，六二所应，乃九五之刚，既引于上而吉矣，孚可知也，故先言「无咎」，而后言「孚」。「升」，九二所应，乃六五之柔，安知其孚与否也？故先言「孚」，而后言「无咎」。是果孚也，则吾用礿也，「利」而「无咎」；不孚而「用礿」，则不唯不利，且有咎矣。今九二以刚德居中，能尽臣道以事上；六五虽柔，而其德谦顺以接下，彼此皆至诚相孚，故二之「用礿」也，礼虽简，亦「无咎」。九三：升虚邑。</p><p>三与上应，而「坤」之顺在前，更无阻碍，则其升也，如入无人之境，故曰「升虚邑」，言至易也。</p><p>六四：王用亨于岐山，吉，无咎。二应五，升将何之？故不言「升」。四近五，圣人嫌其逼五，故亦不言「升」，而别取祭享之义。曰「王用亨于岐山」，亨，许两反，与随上六同，皆当作祭享之「享」。六四在升之时，其德最为柔顺。王者得此占，用此爻义。动而有事于山川，则诚意上升，足以达于神明，故「吉」。六五：贞吉，升阶。</p><p>「贞」者，固守以正而不变也。「升阶」，犹言践阼。先言「贞吉」，而后言「升阶」，盖「贞吉」然后可以升天子之位也。六五以阴柔居尊，而其位不正，故为此戒。</p><p>上六：冥升，利于不息之贞。</p><p>升至于上，极矣。上六以阴爻处「坤」阴之极，知进而不知退，非冥而何？得此占者，唯利于不息之「贞」。「贞」者，固守以正也。正而不息则利，不正而不息则不利也。䷮ 坎下兑上</p><p>困，亨。贞，大人吉，无咎，有言不信。</p><p>困者，穷而惫乏之义。困、井二卦，以坎下坎上取义。井以水上出为功，困以水下漏为阨，又阳刚为阴柔揜蔽，所以为困也。「亨」，以二体言，为卦内坎险，外兑说，在险而以道自说，是以身虽困而道则亨也。曰「贞」，曰「大人吉无咎」，皆指九二；「有言不信」，则指上六。困之成卦，盖在此两爻也。九二陷于坎险中，能以贞道处困而不变，故「吉」而「无咎」。上六兑口之说，非不能言，然处困阨之极，唯宜默耳有言，则人谁信之？徒尚口辩，无益也。初六，臀困于株木，入于幽谷，三岁不觌。</p><p>「株木」，槎蘖之木。初六处困，而在下卦之底，其位又不当，如臀坐株木而不得其安，柔弱不能自拔，如入于幽谷，阴暗而不见其明，困之甚也。「觌」，私见也。初欲应四，而二间之，四亦「困于金车」，未能与之私见，故「三岁不觌」。止云「三岁」，圣人不绝人以终困也。</p><p>九二，困于酒食，朱绂方来，利用亨祀，征凶，无咎。</p><p>九二虽在困中，而不失其所守，但以醉饱过伤，而反为酒食所困耳，故曰「困于酒食」。上有刚中之君，与二同德，必将下来相求，故曰「朱绂方来」。困之时，不宜变动而用事，唯宜享祀耳。九二以刚德居中，其心至诚专一，自能感通于上，故曰「利用享祀」。处困之道，静而处下可也，岂宜往哉？往则必凶，故曰「征凶」。而又曰「无咎」，何也？曰：君命召，则不容不往也，何咎之有？</p><p>六三，困于石，据于蒺蔾，入于其宫，不见其妻，凶。</p><p>承乘皆刚，进则有九四之辱，退则有九二之危，故其象为「困于石，据于蒺蔾」。「宫」，所居之室也。三内体，故言「宫」。其应在上，上兑女，三坎男，上盖三之妻也，而与三不相应，故其象占又为「入于其宫，不见其妻，凶」。</p><p>九四，来徐徐，困于金车，吝，有终。</p><p>自外而内为来。「徐徐」，缓也。九四「来徐徐」，盖与初六「三岁不觌」相发。初之所以「三岁不觌」者，以九四之「来徐徐」也。「金车」，兵车也，为五所乘，不得不黾勉从事乎五，是以有「金车」之困。唯其「困于金车」，是以来徐徐而至于三岁。既历三岁，故始虽不觌，今则「觌」，始虽吝，终则有与也。大抵力不足而过劳则困乏，非有援助则莫能济，况居困之时乎？四与初虽相应，而初以柔居刚，固不能济四之困。四以刚居柔，亦不能济初之困。所以「吝」而乃有终者，它爻皆无应，四独有应初之柔，虽不能相济，毕竟有与也，岂不胜于无与而孤立者哉？</p><p>九五，劓刖，困于赤绂，乃徐有说，利用祭祀。</p><p>「劓」谓刑上六以去在上之小人。「刖」谓刑六三以去在下之小人。三与上同恶相济以揜君子，不去之，则九二莫能上达也。「赤绂」犹坤言「黄裳」，皆下体之服。以人臣在上而不僭，则为「黄裳」；以人君在上而接下，则为「赤绂」。五求二以共济天下之困，而二未至，五乃侧席以待，盖焦心劳思之甚，是「困于赤绂」也。夫以九五刚中之君，下求九二刚中之臣，何为「乃徐有说」耶？以小人未去故也。小人去，则二、五相遇，然后有君臣相得之说也。处困之时，五与二皆以刚德居中，用之于祭祀，则其心至诚专一，足以通于鬼神，故其占又为「利用祭祀」。释文云：「祭祀，本作享祀。」</p><p>上六：困于葛藟，于臲卼，曰动悔有悔，征吉。</p><p>葛生于下，其藤蔓攀附于上。上之应在三，彼此皆柔，犹葛藟之缠绕，故曰「困于葛藟」。臲卼，高危不安貌。处上卦之上，而又下乘九五之刚，故曰「于臲卼」。六三欲牵引上六以为己援，然是时困极将变，上六不自为计，则虽悔无及矣。「曰」者，自谓也。「动悔有悔，征吉」，谓动而悔前之失，知有后悔，则莫如脱去六三之缠绕，而自为征行之计，则「吉」也。䷯ 巽下坎上</p><p>井，改邑不改井，无丧无得，往来井井。汔至，亦未繘井，羸其瓶，凶。</p><p>困、井二卦，以坎水之上下取义。坎水在兑泽之下，则为「困」；在巽木之上，则为「井」。井者，穴地出水之处。井之为卦，下巽入上坎，水入乎水而上水，故谓之「井」。古者八家为井，四井为邑。邑有时而变迁，井则不变迁，故曰「改邑不改井」。「井」乃困之倒体，因倒转为「井」，则六三变为六四，「改邑」之象也。二五之刚中如旧，「不改井」之象也。井之泉，不以常汲而竭，亦不以不汲而盈，故曰「无丧无得」。困，下坎上兑，中互离、巽。井，下巽上坎，中互兑、离。昔为困，具此四卦；今为井，亦具此四卦。此「无丧无得」之象也。往者汲于此，来者汲于此，故曰「往来井井」。「汔」，几也。「繘」，汲水之绠。「瓶」，汲水之器。「羸」，绾绊也。「汔至」而「亦未繘」者，几及于泉而不得泉，则与「未施繘」无异也。「汔至亦未繘」为句，「井羸其瓶」为句。彖传之误，亦承彖辞之误云尔。民非水火不生活，今其瓶羸于井中而凶，谓汲者非其任也。「汔」，与「汔济」之「汔」同。「羸」，与「羸角」、「羸豕」之「羸」同。</p><p>初六：井泥不食，旧井无禽。</p><p>卦以阳爻为泉，阴爻为井。「泥」，如字。初象井底处至下，而水未离乎「泥」也。井有泥则污浊，故不可食。「困」以六居初，倒转为井。「井」亦以六居初，是「未改邑」之前，旧有此井，故谓之「旧井」。「禽」，与擒同。易以阳实为有，阴虚为「无」。初六乃阴爻，是无所获也，故曰「无禽」。「师」六五之应乃九二，故言「有禽」。「恒」九四之应乃六二，故言「无禽」。彼指应爻，此则本爻自谓也。</p><p>九二：井谷射鲋，瓮敝漏。</p><p>九二之井，亦「旧井」也。渫之则其下泉眼通，甃之，则其旁土坚实。九二则犹「未渫」、「未甃」也。「井谷」，指六四，谓井中之虚处，井旧而弗甃，则其旁崩溃为谷也。「射」，食亦反，溅也。「鲋」，乃井𫚥，指初六也。井既崩溃，土必不坚实，土块堕入于井，则其水激溅而射于「鲋」也。「瓮」，乃汲器，指九五也。敝漏则不能受，又安能汲？九二阳爻虽有水，然上无正应，而下比初六，功不上行，故其象如此。</p><p>九三，井渫不食，为我心恻，可用汲，王明，并受其福。「渫」者，浚而澄治之，以喻君子之修洁也。井既渫，则「可食」，而犹「不食」，以喻君子之未见用也。「我」，三自谓。心恻，指上，上与三相应，盖知我而为我心恻者也。「恻」，伤之也。但能伤其可食而不食，可用而未用，非能汲之也。孰能汲之？其九五乎？九五，王也。王明而用三，则上下并受其福。否则，君子沈于下僚，亦犹井虽渫而不用汲，何福之有？六四，井甃，无咎。</p><p>「甃」者，垒砖以为井壁也。三既渫而为新井矣，四不甃，则崩溃不已，必至于湮塞，能「无咎」乎？才虽不足以济物，然能自修治，故亦「无咎」。九五，井冽寒泉，食。</p><p>三既「渫」，四既「甃」，至五则「冽」矣。「冽」者，清之至也。九五爻位俱阳，故「冽」。既「冽」且「寒」，此井泉之至美而可食者也。三居井之半，其水仅半井，而去泥未远，故虽「渫」而人亦「不食」。至五，则水满井矣，去泥甚远，而清洁如此，故「食」。井以上出为功，五未及乎上，故不言「吉」。</p><p>上六：井收勿幕，有孚，元吉。「收」，如字，疑即汲字，讹为「收」尔。「幕」，当作「幂」，揜之也。井养而不穷，盖以济人利物为功。邑有井，则居者、行者皆得而汲之。况继泽无水之困后，正当济人之困，而使之汲、幂之可乎？上与三相应，三「井渫不食」，知上六为己而「心恻」，则其相孚也久矣。今井道成于上而「元吉」，盖由九三渫治之功也。䷰ 离下兑上</p><p>革，巳日乃孚，元亨利贞，悔亡。「革」，变也。革、鼎二卦，皆以离上离下取义。木入火中则然，烹饪用鼎之象也。金在火上则镕，改变从革之象也。「巳日」，已革之日也。「孚」，信也。古者垂法于象魏，特旧法耳，犹浃日而敛之，况变旧而从新乎？夫人之情，可与习常，难与适变。可与乐成，难与虑始。变革之初，四海之广，万姓之众，才识智愚之不齐，人己利害之不同，岂即日所能使之遽信哉？故必巳日而后信也。天下之事，壅滞而颓弊之极，不容不革，革之所以致其通。易穷则变，变则通。「革」之为卦，内文明，外和说，故有大通之道也。事以有悔而后革，无悔则安用革？革虽有大通之道，又宜固守以正，其悔乃亡。否则所革未当，又有变动之悔也。</p><p>初九，巩用黄牛之革。</p><p>「巩」，固也。「黄牛之革」，指六二。「黄」，中色。「牛」，顺畜。「革」，柔而坚靱之物。初居革之始，在下而无应，岂宜妄动而骤有变革？以中顺之道固之可也。初九刚阳而离体，火性炎上，勇于有为，故为此戒。「革」之义，本训变，而皮革所以固物，盖借用耳。如履之为「礼」，噬嗑之为「市」，合占法例如是也。兽皮本硬物，治去其毛而熟之，则变而为柔。盖皮革之革，亦取变之义也。</p><p>六二，巳日乃革之，征吉，无咎。</p><p>爻至三为终日，过三则为巳日。二其日之正中欤？彖言「革，巳日乃孚」，爻则曰「巳日乃革之」，得无异乎？曰：彖言王朝之革，爻则言侯国之革。</p><p>六二曰「巳日乃革之，征吉，无咎」，盖待上之人已革而后革之，则征吉而无咎也。「乃」之云者，必巳日然后可革。今离日方中，盖未已也。日未已，则未可遽革也。六二柔顺中正，而所为不僭，故其象占如此。</p><p>九三，征凶，贞厉，革言三就，有孚。</p><p>「征」，动而行也。「贞」，静以守也。征凶则贞必吉，征吉则贞必凶。今言「征凶」，又言「贞厉」，何也？曰：时未可为，不可遽为，征则凶也。事有当革，不可不革，贞则厉也。六二柔而得中，动则不至于过，故许之曰「征吉」。九三刚而不中，又在离体之极，恐其躁动，故戒之曰「征凶」。复恐其以刚明自任，故又戒之曰「贞厉」。三，去声。「革言三就」，谓谋之再三而后成就也。上与三应，三至上凡历三爻，故曰「三就」。犹士丧礼云：「马缨三就。」注云：「缨当胸，削革为之。」三就，三重三匝也。革言如此，则其「有孚」可知矣。</p><p>九四：悔亡，有孚改命，吉。</p><p>九四刚而不中，本当有悔，然以刚居柔而不暴，必待巳日而后革，革而当者也，是以「悔亡」。彖言「巳日乃孚」，又言「悔亡」，盖与九四相发。将革而谋之，谓之言；革而行之，谓之命。四上孚于五，下孚于三，上下相孚，而后改其命令，故「吉」。四在离日之外，日既已矣，故言「改」。五与上在既改之后，则言「变」。变乃革之成，改则犹未也。「革」之下三爻，皆有谨重而不敢轻改之意，至四而犹未敢轻变，古人之重改作盖如此。</p><p>九五：大人虎变，未占有孚。九五大人为革之主，其德日新，其威足以服人，彰彰然在人耳目，天下皆望而畏之，故曰「大人虎变」。占所以决疑，「未占有孚」，孚之素也。「大人」者，与鬼神合其吉凶者也，况又顺天应人，而时有变革之象，已炳然如虎之文，盖无有不孚者，故无待乎质诸鬼神而后无疑也。三、四、五同互乾体，故皆言「有孚」。</p><p>上六：君子豹变，小人革面，征凶，居贞吉。</p><p>九五：大人出为革之主，如虎之变，天下靡不畏服。凡为君子者皆自新，如豹之换毛；为小人者，亦皆改过而回心向道，故曰：「君子豹变，小人革面。」「面」者，向之谓。革至于上，革道成矣，不必一一吹毛而求其疵也。往则自取多事，而有纷更之凶，故唯守静而居贞则「吉」。䷱ 巽下离上 「鼎」，元吉，亨。</p><p>易全卦取物象命名，唯「井」与「鼎」。井之上坎水，鼎之上离火，而下卦皆「巽」，盖水以绠汲，火以薪传也。「鼎」，器也，非特有安重之义，盖其致洁以为烹饪之用，则又有新义，为卦内巽顺，外文明。又六五以柔中之德居尊，而下应九二刚中之臣，故「亨」。「吉」字，羡文，当依伊川程子作「鼎元亨」。观彖传可见。</p><p>初六：鼎颠趾，利出否。得妾以其子，无咎。</p><p>初在鼎之底，故象「趾」。往与四应，则其趾向上，是为「颠趾」。「否」，悲己反，不臧也。夫「颠趾」，非鼎之正，何利之有？盖「鼎」初「颠趾」，则宿昔渍秽不臧之物，皆颠覆而出之，因以致其新洁，乃所以为「利」也。夫烹饪之初，不去其宿秽，则为新物之害。初六阴柔之资，不中不正，如小人内怀不善，因经颠覆之祸，乃去其不善以从善，是亦「利」也。「妾」，指四。「得妾」，谓买妾而得其人也。生子不以妻而以妾，岂能「无咎」？今得妾而「无咎」者，以其有子故也。在「鼎」之初，有子以主器，又何咎焉？</p><p>九二，鼎有实，我仇有疾，不我能即，吉。</p><p>易以阳爻为实，九二阳实居中，「鼎有实」之象也。「我仇有疾」，指初六，谓初六阴柔，与己相并，而有否恶之疾，非嘉偶也。「即」，就也。与诗东门之𫮃「子不我即」之「即」同。「不我能即吉」者，初方颠覆，自救不暇，安能我即？然而阴从阳者也，我虽自守，彼必相求，我当有以却之，使不来即我，则「吉」。盖鼎中有实，唯当上奉六五之正应，不可使小人近比，而得以染指也。</p><p>九三，鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉。</p><p>「耳」，数偶而中虚，所以受铉也。九三乃刚阳之实，而其数奇，是改变其所以为耳之义，故曰「鼎耳革」。或疑耳在五，何为三又言耳？曰：三当鼎腹，耳虽出于鼎口之上，盖根于鼎腹也。凡物皆以足行，唯鼎以耳行。耳既不可受铉，安能举之以行？故曰「其行塞」。鼎不行，则虽有美味，亦不得而食之，故曰「雉膏不食」。阴阳和则雨。三与五同功，又同互兑体，又九六相合，是「方雨」也。「亏」，欠而不足也。「悔」，自省其失也。三与上不相应，得五而失上，岂非三之所欠而不足者乎？五与三同此鼎耳，三虽革，五不革也。逮夫五受上九之铉而行，则三也亦与之俱行，是故始虽有悔，终亦吉也。</p><p>九四，鼎折足，覆公𫗧，其形渥，凶。</p><p>四本鼎腹，非鼎足也。四与初应，初六之柔在下，不能胜其重任，犹鼎之折足也。大臣任非其人，而败乃公事，犹鼎折足而颠覆其中之实也。圣人烹以享帝养贤，非为口腹之私，是为公𫗧。「形渥」，当作「刑剭」，古有屋诛之法，谓所杀不于市，而适甸师氏者也。四居大臣之位，刚而不中，所应者柔，故其象如此，其占则凶。</p><p>六五，鼎黄耳、金铉，利贞。</p><p>六五位居鼎耳，中而不偏，虚而能受，故曰「黄耳」。铉，贯于鼎耳，所以举鼎而行也。「金」，坚刚之物，指上九而言。以六五而承上九，犹鼎之黄耳而得「金铉」也。其象如此，而其占则为「利贞」，谓宜固守其中德而不可变也。六五质本阴柔，恐其所守不固，是以戒之。</p><p>上九，鼎玉铉，大吉，无不利。鼎之铉，一而已，岂有两铉哉？今叠见焉。五耳有铉，而非铉之正位，上乃正位也。五称上为「金铉」，以其刚也。上乃自称为「玉铉」，何也？金一于刚，玉则具刚柔之德也。上九以刚居柔，故称「玉铉」。鼎至上九，鼎功已成，而有济人之用，吉之大者也。用以享帝亦利，用以养贤亦利，故曰「无不利」。䷔ 震下震上</p><p>震，亨。震来虩虩，笑言哑哑。震惊百里，不丧七鬯。「震」，动也。一阳动于二阴之下也。卦叠两震，则动于下而达于上，故「亨」。震之象为雷。「来」，谓雷声之来。「虩」，许逆反。「虩虩」，与「苏苏」、「索索」，皆雷声。「震来虩虩」，谓雷之初来，而其声震动也。「哑」，乌格反。「哑哑」，惊而辍声也。「笑言哑哑」，谓笑者言者闻雷声之虩虩，遂哑哑然噤无一声也。震以雷言，惊以人言。「百里」，不特谓雷声达于百里，盖以震之长子言。古者王畿千里，诸侯之国皆方百里。震虽乾君之长子，其位则诸侯，故称「百里」。「丧」，失也。「匕鬯」，祭物也。「七」之状如毕，用以举鼎实者。「鬯」乃秬黍酒和郁金，用以灌地降神也。「不丧七鬯」，谓长子主器，而能尽其诚敬之心，不失其所守也。祭物亦多矣，必曰「七鬯」者，以震卦继鼎卦之后也。此卦两体皆震，有长子继长子为君之象。盖百里之命，寄于长子一身，唯能常怀敬畏，如当雷声震惊百里之时，则可以保守百里之国，而不失为宗庙社稷之祭主也。彖辞凡三言震：「震，亨」，总上下二体而言震之所以「亨」。次言「震来虩虩」，盖指下卦；又言「震惊百里」，则指上卦重震。</p><p>初九，「震来虩虩」，后「笑言哑哑，吉」。</p><p>震之彖辞，见于初九。初九，震之主爻也。于「笑言哑哑」之上，添一「后」字，谓闻雷之初来，其声虩虩，而后笑者亦不笑，言者亦不言也。处震之初，而恐惧如此，则获安静和平之福，故又于「笑言哑哑」之下，添一「吉」字。</p><p>六二，震来厉，亿丧贝，跻于九陵，勿逐，七日得。</p><p>「震来」，指初。「厉」，谓雷声之厉。「亿」，当依虞翻作「噫」，于其反与「哑哑」不同。「哑哑」者，「震来」之初，卒然闻之，遂辍声，是为「哑哑」。「噫」，则震之近而可畏，遂失声，是为「噫」。「丧」，失也。「贝」，指初九之刚阳，六二阴柔所资以为助者也。「跻」，登也。「九陵」，指九四。初之应在四，初往应四，则既「跻于九陵」矣，二安能得其助，是「丧贝」也。然在重震之时，诸爻皆不相应，何况九四陷于坎险，则初之往也，势不容留，故虽「跻于九陵」，不久当复还初。复还，则二之所丧，勿用追逐，不久亦复得也。卦爻凡六，而言「七日」，何哉？天道好还，七日则周而复始也。</p><p>六三，震苏苏，震行无眚。</p><p>「苏」，舒缓也。震至六三，则雷声舒缓而少息也。「震行」，谓雷之行。雷当作「声」。之时，动而行于天下，则万物靡不畅达，乃无灾眚。若于当行之时，止而不行，则万物其不遂夭阏于是乎？故行则无眚，不行则有眚。君子于此，体震之行而不止，则亦无眚。盖三虽震体之动，而互艮止，恐其止而不行，故勉之使行也。九四，震遂泥。</p><p>初九之「震」，始震也，得位而在初，故其震也声甚大。九四之「震」，瀳震也，失位而在四阴之中，则其震也沉滞而声不扬，与初九不侔矣，故曰「震遂泥」。「遂」，言其无返之意。泥，乃计反，沉滞也。</p><p>六五，震往来，厉，亿无丧有事。</p><p>初曰「震来」，言雷声方震动而来。二曰「震来」，指初之来。以五视初，则初之始震为既往，四之瀳震为复来，五盖震往而复来之时也。「厉」，谓雷声之厉也。「亿」，与二之「亿」，皆当作「噫」，中心恐惧而失声也。二、五皆中爻主心，故皆言「噫」。「无丧」，即不丧匕鬯之谓。二乘初之始震，出于不意，故「丧其贝」。五乘四之瀳震，畏而知戒，故无所丧。「有事」，谓有事于宗庙社稷，以为祭主也。震之主爻在初，而「无丧有事」乃归之五，五乃震之君也。易道尊君而卑臣，例如此。</p><p>上六，震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。</p><p>索，桑落反。上六处重震之极，雷声渐小而渐消散，故曰「震索索」。「矍矍」，两目左右顾而不定貌，即汉光武谓「马援矍铄哉」之「矍」。以阴柔处动极，故其「视矍矍」。下无正应，征将何之？盖动极则当静，征行则必凶，故戒之曰：「视矍矍，征凶。」「躬」，上之本体。「邻」，为近己者，六五是也。四之震在五为近，在我则隔于五，盖犹未及我也，故曰「震不于其躬，于其邻」。能恐惧修省于震未及身之前，故亦无咎。「婚媾有言」，羡文，观爻、传不释可见。周易集说卷八，</p>',74)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
